AssistantMessageToolRequest(name='create', tool_call_id='tooluse_9ImTg7p7C48Do7eRcarYTS', arguments={'file_text': '/**
 * E-commerce Home Page Script
 * Handles interactive features: cart management, form submissions, and accessibility
 */

// ============================================
// Cart Management
// ============================================

let cart = [];

document.querySelectorAll('.add-to-cart-btn').forEach(button => {
    button.addEventListener('click', addToCart);
});

function addToCart(event) {
    const button = event.target;
    const productId = button.dataset.productId;
    const productCard = button.closest('.product-card');
    const productName = productCard.querySelector('.product-name').textContent;
    const price = productCard.querySelector('.price').textContent;

    cart.push({
        id: productId,
        name: productName,
        price: price
    });

    updateCartBadge();
    showFeedback(button, 'Added to cart!');
}

function updateCartBadge() {
    const badge = document.querySelector('.cart-badge');
    badge.textContent = cart.length;
}

function showFeedback(element, message) {
    const originalText = element.textContent;
    element.textContent = message;
    element.style.background = 'var(--color-accent-secondary)';
    element.style.color = 'var(--color-text-primary)';

    setTimeout(() => {
        element.textContent = originalText;
        element.style.background = '';
        element.style.color = '';
    }, 2000);
}

// ============================================
// Newsletter Form
// ============================================

function handleNewsletterSubmit(event) {
    event.preventDefault();

    const emailInput = document.getElementById('email-input');
    const messageDiv = document.getElementById('newsletter-message');
    const email = emailInput.value.trim();

    if (!email) {
        messageDiv.textContent = 'Please enter a valid email address.';
        messageDiv.style.color = 'var(--color-error)';
        return;
    }

    messageDiv.textContent = '✓ Thank you for subscribing!';
    messageDiv.style.color = 'var(--color-success)';

    emailInput.value = '';

    setTimeout(() => {
        messageDiv.textContent = '';
    }, 5000);
}

// ============================================
// Smooth Scroll for Navigation Links
// ============================================

document.querySelectorAll('a[href^="#"]').forEach(link => {
    link.addEventListener('click', function(e) {
        const href = this.getAttribute('href');
