/* ============================================
   Root Variables & Reset
   ============================================ */

:root {
    --color-bg-dark: #0f1419;
    --color-bg-secondary: #1a1f2e;
    --color-bg-tertiary: #252d3d;
    --color-text-primary: #ffffff;
    --color-text-secondary: #b3b9c4;
    --color-text-muted: #7a8190;
    --color-accent-primary: #8b5cf6;
    --color-accent-secondary: #ec4899;
    --color-accent-tertiary: #06b6d4;
    --color-border: #2a3142;
    --color-hover: #3a4557;
    --color-success: #10b981;
    --color-error: #ef4444;

    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;
    --spacing-3xl: 4rem;

    --border-radius-sm: 0.375rem;
    --border-radius-md: 0.5rem;
    --border-radius-lg: 0.75rem;

    --font-family-base: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --font-size-sm: 0.875rem;
    --font-size-base: 1rem;
    --font-size-lg: 1.125rem;
    --font-size-xl: 1.25rem;
    --font-size-2xl: 1.5rem;
    --font-size-3xl: 2rem;
    --font-size-4xl: 2.5rem;

    --transition-default: 200ms ease-in-out;
    --transition-slow: 300ms ease-in-out;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    background-color: var(--color-bg-dark);
    color: var(--color-text-primary);
    font-family: var(--font-family-base);
    font-size: var(--font-size-base);
    line-height: 1.6;
    letter-spacing: 0.3px;
}

/* ============================================
   Accessibility
   ============================================ */

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-accent-primary);
    color: var(--color-bg-dark);
    padding: var(--spacing-sm) var(--spacing-md);
    text-decoration: none;
    z-index: 100;
    border-radius: var(--border-radius-md);
}

.skip-link:focus {
    top: 0;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* ============================================
   Focus & Interactive States
   ============================================ */

:focus-visible {
    outline: 2px solid var(--color-accent-primary);
    outline-offset: 2px;
}

button:focus-visible,
a:focus-visible,
input:focus-visible {
    outline: 2px solid var(--color-accent-primary);
    outline-offset: 2px;
}

/* ============================================
   Header
   ============================================ */

.header {
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-md) var(--spacing-xl);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-xl);
}

.logo {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    letter-spacing: 3px;
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.navigation {
    flex: 1;
}

.nav-list {
    list-style: none;
    display: flex;
    gap: var(--spacing-2xl);
}

.nav-link {
    color: var(--color-text-secondary);
    text-decoration: none;
    font-size: var(--font-size-sm);
    font-weight: 500;
    transition: color var(--transition-default);
}

.nav-link:hover,
.nav-link:focus {
    color: var(--color-accent-primary);
}

.header-actions {
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
}

.icon-button {
    background: none;
    border: none;
    color: var(--color-text-primary);
    font-size: var(--font-size-xl);
    cursor: pointer;
    position: relative;
    padding: var(--spacing-sm);
    transition: transform var(--transition-default);
}

.icon-button:hover {
    transform: scale(1.1);
}

.cart-badge {
    position: absolute;
    top: -4px;
    right: -4px;
    background-color: var(--color-accent-secondary);
    color: var(--color-text-primary);
    font-size: var(--font-size-sm);
    font-weight: 700;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
    background: linear-gradient(135deg, rgba(139, 92, 246, 0.1), rgba(236, 72, 153, 0.1));
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-3xl) var(--spacing-xl);
    min-height: 500px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-3xl);
}

.hero-content {
    flex: 1;
    max-width: 600px;
}

.hero-title {
    font-size: var(--font-size-4xl);
    font-weight: 700;
    margin-bottom: var(--spacing-lg);
    line-height: 1.2;
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-subtitle {
    font-size: var(--font-size-lg);
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-2xl);
}

.cta-button {
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    color: var(--color-text-primary);
    border: none;
    padding: var(--spacing-md) var(--spacing-2xl);
    border-radius: var(--border-radius-md);
    font-size: var(--font-size-base);
    font-weight: 600;
    cursor: pointer;
    transition: transform var(--transition-default), box-shadow var(--transition-default);
}

.cta-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 20px 40px rgba(139, 92, 246, 0.3);
}

.cta-button:active {
    transform: translateY(0);
}

.hero-image {
    flex: 1;
    height: 400px;
    background: linear-gradient(135deg, rgba(139, 92, 246, 0.2), rgba(236, 72, 153, 0.2));
    border-radius: var(--border-radius-lg);
    border: 1px solid var(--color-border);
}

/* ============================================
   Section Styling
   ============================================ */

.section-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-3xl) var(--spacing-xl);
}

.section-title {
    font-size: var(--font-size-3xl);
    font-weight: 700;
    margin-bottom: var(--spacing-2xl);
    text-align: center;
}

/* ============================================
   Featured Products Section
   ============================================ */

.featured-section {
    background-color: var(--color-bg-dark);
    border-bottom: 1px solid var(--color-border);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-2xl);
}

.product-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: transform var(--transition-default), box-shadow var(--transition-default), border-color var(--transition-default);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 20px 40px rgba(139, 92, 246, 0.15);
    border-color: var(--color-accent-primary);
}

.product-image {
    position: relative;
    overflow: hidden;
    aspect-ratio: 1;
}

.image-placeholder {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--color-bg-tertiary), var(--color-hover));
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-text-muted);
    font-size: var(--font-size-sm);
}

.product-info {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-name {
    font-size: var(--font-size-lg);
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.product-category {
    font-size: var(--font-size-sm);
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-md);
}

.product-rating {
    font-size: var(--font-size-sm);
    margin-bottom: var(--spacing-md);
    color: var(--color-text-secondary);
}

.product-price {
    margin-bottom: var(--spacing-lg);
    flex-grow: 1;
}

.price {
    font-size: var(--font-size-xl);
    font-weight: 700;
    color: var(--color-accent-primary);
}

.add-to-cart-btn {
    background-color: var(--color-bg-tertiary);
    color: var(--color-text-primary);
    border: 1px solid var(--color-border);
    padding: var(--spacing-md) var(--spacing-lg);
    border-radius: var(--border-radius-md);
    cursor: pointer;
    font-weight: 600;
    transition: all var(--transition-default);
}

.add-to-cart-btn:hover {
    background-color: var(--color-accent-primary);
    border-color: var(--color-accent-primary);
    color: var(--color-bg-dark);
}

/* ============================================
   Deals Section
   ============================================ */

.deals-section {
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-2xl);
}

.deal-card {
    position: relative;
    background-color: var(--color-bg-tertiary);
    border: 1px solid var(--color-border);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: all var(--transition-slow);
}

.deal-card:hover {
    border-color: var(--color-accent-primary);
    transform: translateY(-8px);
}

.deal-card-featured {
    grid-column: 1 / -1;
    display: flex;
    gap: var(--spacing-2xl);
}

.deal-card-featured .deal-image {
    flex: 1;
    min-height: 300px;
}

.deal-card-featured .deal-info {
    flex: 1;
    padding: var(--spacing-2xl);
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.deal-badge {
    position: absolute;
    top: var(--spacing-lg);
    right: var(--spacing-lg);
    background: var(--color-accent-secondary);
    color: var(--color-text-primary);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--border-radius-md);
    font-weight: 700;
    font-size: var(--font-size-sm);
    z-index: 10;
}

.deal-image {
    aspect-ratio: 1;
    overflow: hidden;
}

.deal-info {
    padding: var(--spacing-lg);
}

.deal-title {
    font-size: var(--font-size-lg);
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
}

.deal-description {
    font-size: var(--font-size-sm);
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-lg);
}

.deal-button {
    align-self: flex-start;
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    color: var(--color-text-primary);
    border: none;
    padding: var(--spacing-md) var(--spacing-lg);
    border-radius: var(--border-radius-md);
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-default);
}

.deal-button:hover {
    transform: translateX(4px);
}

/* ============================================
   Editorial Section
   ============================================ */

.editorial-section {
    background-color: var(--color-bg-dark);
    border-bottom: 1px solid var(--color-border);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: var(--spacing-2xl);
}

.editorial-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    transition: all var(--transition-default);
}

.editorial-card:hover {
    border-color: var(--color-accent-primary);
    box-shadow: 0 20px 40px rgba(139, 92, 246, 0.15);
}

.editorial-image {
    overflow: hidden;
    background-color: var(--color-bg-tertiary);
}

.editorial-content {
    padding: var(--spacing-lg);
}

.editorial-meta {
    display: flex;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-sm);
}

.editorial-category {
    color: var(--color-accent-primary);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.editorial-date {
    color: var(--color-text-muted);
}

.editorial-title {
    font-size: var(--font-size-lg);
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    line-height: 1.4;
}

.editorial-excerpt {
    font-size: var(--font-size-sm);
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-lg);
}

.read-more {
    color: var(--color-accent-primary);
    text-decoration: none;
    font-weight: 600;
    transition: color var(--transition-default);
    display: inline-block;
}

.read-more:hover,
.read-more:focus {
    color: var(--color-accent-tertiary);
}

/* ============================================
   Newsletter Section
   ============================================ */

.newsletter-section {
    background: linear-gradient(135deg, rgba(139, 92, 246, 0.1), rgba(236, 72, 153, 0.1));
    border: 1px solid var(--color-border);
}

.newsletter-section .section-container {
    text-align: center;
}

.newsletter-title {
    font-size: var(--font-size-3xl);
    font-weight: 700;
    margin-bottom: var(--spacing-lg);
}

.newsletter-subtitle {
    font-size: var(--font-size-lg);
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-2xl);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-md);
    max-width: 500px;
    margin: 0 auto var(--spacing-lg);
}

.email-input {
    flex: 1;
    background-color: var(--color-bg-tertiary);
    border: 1px solid var(--color-border);
    color: var(--color-text-primary);
    padding: var(--spacing-md) var(--spacing-lg);
    border-radius: var(--border-radius-md);
    font-size: var(--font-size-base);
    transition: border-color var(--transition-default);
}

.email-input::placeholder {
    color: var(--color-text-muted);
}

.email-input:focus {
    border-color: var(--color-accent-primary);
}

.newsletter-button {
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    color: var(--color-text-primary);
    border: none;
    padding: var(--spacing-md) var(--spacing-2xl);
    border-radius: var(--border-radius-md);
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-default);
}

.newsletter-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 20px rgba(139, 92, 246, 0.3);
}

.newsletter-message {
    font-size: var(--font-size-sm);
    color: var(--color-success);
}

/* ============================================
   Footer
   ============================================ */

.footer {
    background-color: var(--color-bg-secondary);
    border-top: 1px solid var(--color-border);
    color: var(--color-text-secondary);
    padding: var(--spacing-3xl) 0 var(--spacing-2xl);
}

.footer-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-xl);
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-2xl);
    margin-bottom: var(--spacing-2xl);
}

.footer-title {
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-text-primary);
    margin-bottom: var(--spacing-lg);
}

.footer-list {
    list-style: none;
}

.footer-list li {
    margin-bottom: var(--spacing-md);
}

.footer-list a {
    color: var(--color-text-secondary);
    text-decoration: none;
    transition: color var(--transition-default);
    font-size: var(--font-size-sm);
}

.footer-list a:hover,
.footer-list a:focus {
    color: var(--color-accent-primary);
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-xl);
    border-top: 1px solid var(--color-border);
    padding-top: var(--spacing-xl);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-lg);
}

.footer-bottom p {
    font-size: var(--font-size-sm);
}

.footer-meta {
    list-style: none;
    display: flex;
    gap: var(--spacing-xl);
}

.footer-meta a {
    color: var(--color-text-secondary);
    text-decoration: none;
    font-size: var(--font-size-sm);
    transition: color var(--transition-default);
}

.footer-meta a:hover,
.footer-meta a:focus {
    color: var(--color-accent-primary);
}

/* ============================================
   Responsive Design
   ============================================ */

@media (max-width: 768px) {
    .header-container {
        flex-wrap: wrap;
        gap: var(--spacing-md);
    }

    .nav-list {
        order: 3;
        width: 100%;
        gap: var(--spacing-lg);
    }

    .hero {
        flex-direction: column;
        padding: var(--spacing-2xl) var(--spacing-lg);
        min-height: auto;
    }

    .hero-image {
        height: 300px;
    }

    .hero-title {
        font-size: var(--font-size-3xl);
    }

    .deal-card-featured {
        flex-direction: column;
        gap: var(--spacing-lg);
    }

    .deal-card-featured .deal-image {
        min-height: auto;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .footer-bottom {
        flex-direction: column;
        text-align: center;
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-lg: 1rem;
        --spacing-xl: 1.5rem;
        --font-size-4xl: 2rem;
        --font-size-3xl: 1.5rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .deal-card-featured {
        grid-column: 1;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .section-container {
        padding: var(--spacing-2xl) var(--spacing-md);
    }
}

/* ============================================
   Forced Colors Mode (High Contrast)
   ============================================ */

@media (forced-colors: active) {
    .product-card,
    .deal-card,
    .editorial-card {
        border: 2px solid CanvasText;
    }

    .product-card:hover,
    .deal-card:hover,
    .editorial-card:hover {
        border-color: Highlight;
    }

    .cta-button,
    .add-to-cart-btn,
    .deal-button,
    .newsletter-button {
        border: 2px solid CanvasText;
        background-color: Canvas;
        color: CanvasText;
    }

    .cta-button:focus-visible,
    .add-to-cart-btn:focus-visible,
    .deal-button:focus-visible,
    .newsletter-button:focus-visible {
        outline: 2px solid Highlight;
        outline-offset: 2px;
    }
}

/* ============================================
   Reduced Motion
   ============================================ */

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    html {
        scroll-behavior: auto;
    }
}

/**
 * E-commerce Home Page Script
 * Handles interactive features: cart management, form submissions, and accessibility
 */

// ============================================
// Cart Management
// ============================================

let cart = [];

document.querySelectorAll('.add-to-cart-btn').forEach(button => {
    button.addEventListener('click', addToCart);
});

function addToCart(event) {
    const button = event.target;
    const productId = button.dataset.productId;
    const productCard = button.closest('.product-card');
    const productName = productCard.querySelector('.product-name').textContent;
    const price = productCard.querySelector('.price').textContent;

    cart.push({
        id: productId,
        name: productName,
        price: price
    });

